-- Bind :archive_before and :archive_reason.
INSERT INTO cpf_transaction_lineage_archive (lineage_id,transaction_id,segment_id,parent_segment_id,attempt_no,trace_id,span_id,request_id,idempotency_key,tenant_id,channel_code,actor_id_masked,instance_id,was_id,agent_id,worker_id,remote_system,operation_id,message_id,consumer_group,dlq_id,batch_job_instance_id,batch_job_execution_id,batch_step_execution_id,partition_id,file_id,source_type,source_ref_id,lifecycle_state,failure_stage,unknown_yn,reconcile_state,occurred_at,freshness_at,payload_hash,archived_at,archive_reason,archived_by)
SELECT lineage_id,transaction_id,segment_id,parent_segment_id,attempt_no,trace_id,span_id,request_id,idempotency_key,tenant_id,channel_code,actor_id_masked,instance_id,was_id,agent_id,worker_id,remote_system,operation_id,message_id,consumer_group,dlq_id,batch_job_instance_id,batch_job_execution_id,batch_step_execution_id,partition_id,file_id,source_type,source_ref_id,lifecycle_state,failure_stage,unknown_yn,reconcile_state,occurred_at,freshness_at,payload_hash,SYSTIMESTAMP,:archive_reason,:archived_by FROM cpf_transaction_lineage t WHERE t.occurred_at < :archive_before AND NOT EXISTS (SELECT 1 FROM cpf_transaction_lineage_archive a WHERE a.lineage_id=t.lineage_id AND a.occurred_at=t.occurred_at);
UPDATE cpf_transaction_lineage SET archived_at=SYSTIMESTAMP WHERE occurred_at < :archive_before AND archived_at IS NULL;
